  <script>
    const navToggle = document.querySelector('.nav-toggle');
    const nav = document.getElementById('site-nav');
    const filterButtons = Array.from(document.querySelectorAll('.filter-button'));
    const products = Array.from(document.querySelectorAll('.feature-card'));
    const filterStatus = document.getElementById('filter-status');

    navToggle.addEventListener('click', () => {
      const isOpen = navToggle.getAttribute('aria-expanded') === 'true';
      navToggle.setAttribute('aria-expanded', String(!isOpen));
      nav.dataset.open = String(isOpen);
    });

    const setFilter = (filter) => {
      filterButtons.forEach((button) => {
        const pressed = button.dataset.filter === filter;
        button.setAttribute('aria-pressed', String(pressed));
      });

      let visibleCount = 0;
      products.forEach((product) => {
        const matches = filter === 'all' || product.dataset.category === filter;
        product.classList.toggle('hidden', !matches);
        if (matches) visibleCount += 1;
      });

      filterStatus.textContent =
        filter === 'all'
          ? 'Showing all featured products.'
          : `Showing ${visibleCount} featured product${visibleCount === 1 ? '' : 's'} in ${filter}.`;
    };

    filterButtons.forEach((button) => {
      button.addEventListener('click', () => setFilter(button.dataset.filter));
    });

    document.addEventListener('keydown', (event) => {
      if (event.key !== 'Escape') return;
      if (navToggle.getAttribute('aria-expanded') === 'true') {
        navToggle.setAttribute('aria-expanded', 'false');
        nav.dataset.open = 'false';
        navToggle.focus();
      }
    });
  </script>
